// ═══ EINSTELLUNGEN ═══ Alles, was man anpassen kann, steht hier.
// live = false: auch der Montagslauf schreibt nichts (nur lesen und zählen). Freigabe Admin 13.11.2026 → true.
// Ein manueller Start ist immer ein Trockenlauf (liest Close und die Mailchimp-Zielgruppe, schreibt nichts, hakt nichts ab).
const cfg = {
  live: true,   // Admin 13.11.2026: jeden Montag laufen lassen
  close: { url: 'https://api.close.com/api/v1/lead/', seite: 100 },
  // Mailchimp: Rechenzentrum = Teil des API-Schlüssels nach dem Bindestrich (z. B. 'us21'), Zielgruppe = ID der Liste „Newsletter“.
  mailchimp: { rechenzentrum: 'usXX', zielgruppe: 'YOUR_AUDIENCE_ID' },   // „AGENCY Newsletter“
  // UserA Regeln (Asana-Kommentar 11.11.2026): ohne E-Mail weglassen, „kein Name“ bleibt, Name „Slack“ → leer.
  regeln: { nameLeer: ['slack'] },
  // Admin 13.11.2026: jeden Montag eine neue Prüfaufgabe mit dem Ergebnis an UserA (Projekt Newsletter Erstellung), UserA hakt sie ab.
  asana: { anlegen: true, workspace: 'YOUR_ASANA_WORKSPACE_GID', projekt: 'YOUR_ASANA_NEWSLETTER_PROJECT_GID', zustaendig: 'YOUR_ASANA_USER_A_GID' },
};
if (!/^[a-z]{2}\d{1,3}$/.test(cfg.mailchimp.rechenzentrum) || !cfg.mailchimp.zielgruppe) throw new Error('Einstellungen: Mailchimp-Rechenzentrum oder Zielgruppe fehlt');
const geplant = $('Montag 7 Uhr').isExecuted;
return [{ json: { ...cfg, geplant, schreiben: geplant && cfg.live, start: $now.toISO() } }];

// ═══ KONTAKTE AUFBEREITEN ═══ wie UserA Excel: Hauptkontakt je Lead (erster Kontakt), dessen erste E-Mail, Vorname, Nachname.
// Weggelassen: Lead ohne Kontakt, Kontakt ohne E-Mail, ungültige E-Mail, doppelte E-Mail. Name „Slack“ wird leer, „kein Name“ bleibt drin.
// Vorname/Nachname: Close kennt nur einen Namen, geteilt an der letzten Leerstelle (Annahme, wie der Close-Export).
const cfg = $('Einstellungen').first().json;
const seiten = $input.all().map(i => i.json);
if (!seiten.length || seiten.some(s => !Array.isArray(s.data))) throw new Error('Close: unerwartete Antwort (Feld data fehlt)');
if (seiten[seiten.length - 1].has_more) throw new Error('Close: nicht alle Seiten gelesen (has_more), Abbruch');
const leads = seiten.flatMap(s => s.data);
if (!leads.length) throw new Error('Close: 0 Leads gelesen, Abbruch');
const leer = new Set(cfg.regeln.nameLeer.map(s => s.toLowerCase()));
const gueltig = (e) => /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(e);
const z = { leads: leads.length, ohneKontakt: 0, ohneMail: 0, ungueltig: 0, doppelt: 0, nameLeer: 0 };
const gesehen = new Set(), out = [];
for (const l of leads) {
  const k = (l.contacts || [])[0];
  if (!k) { z.ohneKontakt++; continue; }
  const email = String(((k.emails || [])[0] || {}).email || '').trim().toLowerCase();
  if (!email) { z.ohneMail++; continue; }
  if (!gueltig(email)) { z.ungueltig++; continue; }
  if (gesehen.has(email)) { z.doppelt++; continue; }
  gesehen.add(email);
  let name = String(k.name || '').trim().replace(/\s+/g, ' ');
  if (leer.has(name.toLowerCase())) { name = ''; z.nameLeer++; }
  const i = name.lastIndexOf(' ');
  out.push({ email, vorname: i > 0 ? name.slice(0, i) : name, nachname: i > 0 ? name.slice(i + 1) : '' });
}
if (!out.length) throw new Error('Close: kein Kontakt mit E-Mail-Adresse, Abbruch');
z.uebernommen = out.length;
return out.map((o, n) => ({ json: n === 0 ? { ...o, _zahlen: z } : o }));

// ═══ ARCHIVIERTE HERAUSSUCHEN ═══ Kontakte, die Mailchimp nach dem Eintragen noch als „archived“ meldet.
// Admin 13.11.2026: archivierte Kontakte wieder aktivieren (wie UserA Haken „Archivierung aufheben“).
const a = $input.all().map(i => i.json).filter(x => x.statusCode === 200 && x.body && x.body.status === 'archived')
  .map(x => ({ json: { email: String(x.body.email_address).toLowerCase() } }));
return a.length ? a : [{ json: { keine: true } }];

// ═══ ERGEBNIS ZUSAMMENFASSEN ═══ Zahlen für den Asana-Kommentar (keine E-Mail-Adressen).
// Mailchimp-Antwort je Kontakt (aus „In Mailchimp eintragen“): 200 = eingetragen. „neu“ = Anmeldezeitpunkt (timestamp_opt) in diesem Lauf.
// Archivierte: von „Archivierte reaktivieren“ wieder auf abonniert gesetzt (Admin 13.11.2026).
const cfg = $('Einstellungen').first().json;
const z = $('Kontakte aufbereiten').first().json._zahlen;
const liste = $('Zielgruppe prüfen').first().json;
const r = { modus: cfg.schreiben ? 'live' : 'trocken', ...z, zielgruppe: liste.name, mitglieder_vorher: (liste.stats || {}).member_count };
if (cfg.schreiben) {
  const start = new Date(cfg.start).getTime() - 60000;
  const a = $('In Mailchimp eintragen').all().map(i => i.json);
  const ok = a.filter(x => x.statusCode === 200 && x.body);
  r.archiviert = ok.filter(x => x.body.status === 'archived').length;
  r.neu = ok.filter(x => x.body.status !== 'archived' && x.body.timestamp_opt && new Date(x.body.timestamp_opt).getTime() >= start).length;
  r.aktualisiert = ok.length - r.neu - r.archiviert;
  r.abgemeldet = ok.filter(x => x.body.status === 'unsubscribed').length;
  r.reaktiviert = $('Archivierte reaktivieren').isExecuted
    ? $('Archivierte reaktivieren').all().filter(i => i.json.statusCode === 200 && i.json.body && i.json.body.status === 'subscribed').length : 0;
  const f = a.filter(x => x.statusCode !== 200);
  r.fehler = f.length;
  r.fehler_arten = Object.entries(f.reduce((m, x) => { const t = (x.body && x.body.title) || ('HTTP ' + x.statusCode); m[t] = (m[t] || 0) + 1; return m; }, {})).map(([t, n]) => t + ': ' + n);
  if (!ok.length) throw new Error('Mailchimp: kein Kontakt eingetragen (' + r.fehler_arten.join(', ') + ')');
}
const zeit = $now.setZone('Europe/Berlin').toFormat('dd.MM.yyyy HH:mm');
const text = [
  (cfg.schreiben ? 'Automatischer Abgleich Close → Mailchimp (' : 'Trockenlauf Close → Mailchimp, nichts geschrieben (') + zeit + '):',
  '• Close: ' + z.leads + ' Leads gelesen, ' + z.uebernommen + ' Kontakte übernommen',
  '• Weggelassen: ' + z.ohneMail + ' ohne E-Mail, ' + z.ohneKontakt + ' ohne Kontakt, ' + z.ungueltig + ' mit ungültiger E-Mail, ' + z.doppelt + ' doppelt'
    + (z.nameLeer ? '; bei ' + z.nameLeer + ' „Slack“ als Name leer gelassen' : ''),
  cfg.schreiben
    ? '• Mailchimp „' + r.zielgruppe + '“: ' + r.neu + ' neu abonniert, ' + r.aktualisiert + ' aktualisiert'
      + (r.abgemeldet ? ', davon ' + r.abgemeldet + ' abgemeldet (bleiben abgemeldet)' : '')
      + (r.archiviert ? ', ' + r.reaktiviert + ' von ' + r.archiviert + ' archivierten wieder aktiviert' : '')
      + (r.fehler ? ', ' + r.fehler + ' nicht übernommen (' + r.fehler_arten.join(', ') + ', normal laut UserA)' : '')
    : '• Mailchimp „' + r.zielgruppe + '“: ' + r.mitglieder_vorher + ' Kontakte, nichts geändert',
].join('\n');
const kw = $now.setZone('Europe/Berlin').toFormat('kkkk-WW').replace(/^(\d+)-(\d+)$/, 'KW $2/$1');
const aufgabe_name = 'Newsletter-Abgleich Close → Mailchimp ' + kw + ': prüfen und abhaken';
const aufgabe_notiz = text + '\n\nDiese Aufgabe hat der Workflow „Close → Mailchimp Newsletter (wöchentlich)“ in n8n angelegt. '
  + 'Bitte die Zahlen kurz ansehen und abhaken. Fällt etwas auf (z. B. viel weniger Leads als sonst oder viele Fehler), bitte Admin Bescheid geben.';
return [{ json: { ...r, text, aufgabe_name, aufgabe_notiz, faellig: $now.setZone('Europe/Berlin').toISODate() } }];
